To draw a circle with a radius of 10 pixels in a HTML canvas using JavaScript, you can use the following code:

<html>
  <head>
    <script>
      function drawCircle() {
        var canvas = document.getElementById("myCanvas");
        var context = canvas.getContext("2d");

        context.beginPath();
        context.arc(100, 100, 10, 0, 2 * Math.PI);
        context.fillStyle = "blue";
        context.fill();
        context.stroke();
      }
    </script>
  </head>
  <body onload="drawCircle()">
    <canvas id="myCanvas" width="200" height="200"></canvas>
  </body>
</html>

