const express = require('express');
const path = require('path');
const app = express();

// Serve static files from the 'public' directory
app.use(express.static(path.join(__dirname, 'public')));

// Set up a route to serve the homepage
app.get('/', (req, res) => {
  res.sendFile(path.join(__dirname, 'public/index.html'));
});

// Allow routes without a .html extension to work
app.use((req, res, next) => {
  if (!req.path.includes('.') && req.path !== '/') {
    req.url += '.html';
  }
  next();
});

// Start the server and listen on port 3000
app.listen(3000, () => {
  console.log('Example app listening on port 3000!');
});

In this example, the express.static middleware is used to serve static files from the /public directory, and the path module is used to construct file paths. The route for the homepage sends the index.html file, which is located in the /public directory. The middleware function at the bottom of the code checks whether the requested URL contains a file extension and, if not, adds a .html extension to the URL. This allows URLs without a .html extension to work, as requested.

The quadratic formula can be used to find the solutions to the quadratic equation:

\begin{equation*}
ax^2+bx+c=0
\end{equation*}

The formula is:

\begin{equation*}
x = \frac{-b \pm \sqrt{b^2 - 4ac}}{2a}
\end{equation*}

where $a$, $b$, and $c$ are coefficients of the quadratic equation.

Therefore, the solutions to the quadratic equation are:

\begin{equation*}
x_1 = \frac{-b + \sqrt{b^2 - 4ac}}{2a}
\end{equation*}

\begin{equation*}
x_2 = \frac{-b - \sqrt{b^2 - 4ac}}{2a}
\end{equation*}

Note that the expression inside the square root, $b^2 - 4ac$, is called the discriminant. If the discriminant is negative, the quadratic equation has no real solutions, but it may have complex solutions. If the discriminant is zero, the quadratic equation has one real solution. If the discriminant is positive, the quadratic equation has two real solutions.

